 q('.help-sheet').onclick=e=>{e.stopPropagation();if(helpStart&&Math.hypot(e.clientX-helpStart.x,e.clientY-helpStart.y)>20){helpStart=null;return}helpStart=null;if(e.target.closest('.close-sheet'))return close();if(e.target.closest('.guide-prev')){page=Math.max(0,page-1);drawGuide()}else next()};
 q('.menu-layer125').onclick=e=>{if(e.target===e.currentTarget)close()};
