 function keys(e){if(panel==='none')return;const editable=e.target.matches('input,textarea,select');if(e.key==='Escape'||e.code==='KeyP'&&!editable){e.preventDefault();close();e.stopImmediatePropagation();return}if(e.key==='Tab'){const box=q(panels[panel]),items=[...box.querySelectorAll('button,input')].filter(b=>!b.disabled&&b.getClientRects().length),i=items.indexOf(document.activeElement);if((e.shiftKey&&i<=0)||(!e.shiftKey&&i===items.length-1)){e.preventDefault();items[e.shiftKey?items.length-1:0]?.focus()}}if(panel==='help'&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();if(e.key==='ArrowRight')next();else{page=Math.max(0,page-1);drawGuide()}}e.stopImmediatePropagation()}
 window.addEventListener('keydown',keys,true);const keyRelease=e=>{if(panel!=='none')e.stopImmediatePropagation()};window.addEventListener('keyup',keyRelease,true);window.addEventListener('resize',layout);touchInput.addEventListener('change',layout);
